'use strict';
// A small compatibility layer for the existing game UI; physical contacts use Box2D circles.
(()=>{const P=planck,S=30;let uid=1;const listeners=new WeakMap();function emit(e,n,data={}){for(const f of listeners.get(e)?.[n]||[])f(data)}function wrap(kind,x,y,a,b,o={}){const w={id:uid++,plugin:{},kind,x,y,a,b,options:o,bounds:{min:{},max:{}},positionImpulse:{x:0,y:0},_mass:null,_angle:0,_v:{x:0,y:0},_omega:0,isSleeping:false};Object.defineProperties(w,{position:{get(){const p=w._body?.getPosition();return p?{x:p.x*S,y:p.y*S}:{x:w.x,y:w.y}}},velocity:{get(){const v=w._body?.getLinearVelocity();return v?{x:v.x*S/60,y:v.y*S/60}:w._v}},angle:{get(){return w._body?.getAngle()??w._angle}},angularVelocity:{get(){return(w._body?.getAngularVelocity()??w._omega)/60}},speed:{get(){const v=w.velocity;return Math.hypot(v.x,v.y)}},mass:{get(){return w._body?.getMass()||w._mass||1}},isStatic:{get(){return w._body?.isStatic()??!!o.isStatic}}});return w}
function add(world,entries){for(const w of Array.isArray(entries)?entries:[entries]){const b=world.p.createBody({type:w.options.isStatic?'static':'dynamic',position:P.Vec2(w.x/S,w.y/S),angle:w._angle,allowSleep:false,bullet:true,linearDamping:.20,angularDamping:.08});w._body=b;w._world=world;const shape=w.kind==='circle'?P.Circle(w.a/S):P.Box(w.a/S/2,w.b/S/2);const area=w.kind==='circle'?Math.PI*(w.a/S)**2:w.a*w.b/S**2;b.createFixture(shape,{density:w._mass?w._mass/area:1,friction:w.kind==='circle'?.012:.025,restitution:.065});b.setUserData(w);b.setLinearVelocity(P.Vec2(w._v.x*60/S,w._v.y*60/S));b.setAngularVelocity(w._omega);world.items.push(w)}}
const Matter={Engine:{create(){return{world:{p:new P.World({gravity:P.Vec2(0,31),allowSleep:false}),items:[]},gravity:{y:1.42},timing:{timestamp:0},previous:new Set(),enableSleeping:false}},update(e,ms){emit(e,'beforeSolve');e.world.p.setGravity(P.Vec2(0,e.gravity.y*22));e.world.p.step(ms/1000,10,5);e.timing.timestamp+=ms;const active=[],start=[],keys=new Set();for(let c=e.world.p.getContactList();c;c=c.getNext()){if(!c.isTouching())continue;const a=c.getFixtureA().getBody().getUserData(),b=c.getFixtureB().getBody().getUserData();if(!a||!b)continue;const key=Matter.Pair.id(a,b);keys.add(key);const pair={bodyA:a,bodyB:b};active.push(pair);if(!e.previous.has(key))start.push(pair)}e.previous=keys;emit(e,'collisionStart',{pairs:start});emit(e,'collisionActive',{pairs:active})},clear(e){e.previous.clear()}},Bodies:{polygon(x,y,n,r,o){return wrap('circle',x,y,r,0,o)},rectangle(x,y,w,h,o){return wrap('rect',x,y,w,h,o)}},Body:{setMass(w,m){w._mass=m;if(w._body&&!w._body.isStatic()){const r=(w.circleRadius||w.a)/S;w._body.setMassData({mass:m,center:P.Vec2(0,0),I:.5*m*r*r})}},setVelocity(w,v){w._v=v;w._body?.setLinearVelocity(P.Vec2(v.x*60/S,v.y*60/S))},setAngularVelocity(w,v){w._omega=v*60;w._body?.setAngularVelocity(v*60)},setAngle(w,a){w._angle=a;w._body?.setAngle(a)},setStatic(w,v){w.options.isStatic=v;w._body?.setType(v?'static':'dynamic')}},Composite:{add,allBodies(w){return w.items.slice()},get(w,id){return w.items.find(b=>b.id===id)},remove(w,b){if(b._body){w.p.destroyBody(b._body);b._body=null}w.items=w.items.filter(x=>x!==b)},clear(w){for(const b of w.items)if(b._body)w.p.destroyBody(b._body);w.items=[]}},Events:{on(e,name,f){if(!listeners.has(e))listeners.set(e,{});const o=listeners.get(e);(o[name]??=[]).push(f)}},Sleeping:{set(w,v){w.isSleeping=false;w._body?.setAwake(true)}},Pair:{id(a,b){return[Math.min(a.id,b.id),Math.max(a.id,b.id)].join(':')}},Collision:{collides(a,b){const dx=b.position.x-a.position.x,dy=b.position.y-a.position.y,d=Math.hypot(dx,dy),depth=a.circleRadius+b.circleRadius-d;return depth>=0?{normal:{x:-dx/(d||1),y:-dy/(d||1)},depth}:null}}};window.Matter=Matter;
})();
